/**
 * Confluence Node - Version 1
 * Discriminator: resource=page, operation=getLabels
 */


interface Credentials {
  confluenceCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** List the labels on a page */
export type ConfluenceV1PageGetLabelsParams = {
  resource: 'page';
  operation: 'getLabels';
  authentication?: 'cloudOAuth2' | 'serviceAccount';
/**
 * The Confluence site to use. Can be left empty when the connection has access to exactly one site.
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * Limits page selection and By Title lookups to one space. Leave empty or pick "All Spaces" to search across all spaces.
 * @searchListMethod searchSpacesWithAll
 * @default {"mode":"list","value":""}
 */
    space?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The page whose labels to list
 * @searchListMethod getPages
 * @default {"mode":"list","value":""}
 */
    page?: { __rl: true; mode: 'list' | 'url' | 'id' | 'title'; value: string; cachedResultName?: string };
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Return only labels from one namespace. Every label belongs to exactly one, shown as the "prefix" field on each result. Leave this option out to return labels from all namespaces.
     * @default global
     */
    prefix?: 'global' | 'my' | 'system' | 'team' | Expression<string>;
    /** The field to order the labels by
     * @default name
     */
    sortBy?: 'created-date' | 'id' | 'name' | Expression<string>;
    /** The direction to order in. Only applies when Sort By is set.
     * @default asc
     */
    sortDirection?: 'asc' | 'desc' | Expression<string>;
  };
};

export type ConfluenceV1PageGetLabelsNode = {
  type: 'n8n-nodes-base.confluence';
  version: 1;
  config: NodeConfig<ConfluenceV1PageGetLabelsParams> & { credentials?: Credentials };
};